/**
 * Main World Interceptor for Google AI Studio
 * Runs in the webpage context (world: "MAIN") to intercept genuine Audio Blobs and AudioContext buffers
 * directly as they are generated by Google AI Studio, bypassing CSP and isolated world boundaries.
 * Author: Faiz_Fahmi_ID
 */

(() => {
  if (window.__AI_TTS_MAIN_WORLD_INTERCEPTOR_ACTIVE__) return;
  window.__AI_TTS_MAIN_WORLD_INTERCEPTOR_ACTIVE__ = true;

  console.log('[AI TTS Main World Interceptor] Hooked into Google AI Studio context.');

  function sendAudioBuffer(arrayBuffer, source) {
    if (!arrayBuffer || arrayBuffer.byteLength < 400) return;
    try {
      // Validate RIFF header if available or audio data
      const header = String.fromCharCode(...new Uint8Array(arrayBuffer.slice(0, 4)));
      console.log(`[AI TTS Interceptor] Audio buffer captured from ${source}:`, arrayBuffer.byteLength, 'header:', header);

      const bytes = new Uint8Array(arrayBuffer);
      let binary = '';
      const len = bytes.byteLength;
      for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
      }
      const base64 = btoa(binary);

      window.postMessage(
        {
          type: '__AI_TTS_BLOB_DATA_CAPTURED__',
          base64Data: base64,
          size: arrayBuffer.byteLength,
          mime: 'audio/wav',
          header,
          source,
        },
        '*'
      );
    } catch (e) {
      console.warn('[AI TTS Interceptor] Error sending audio buffer:', e);
    }
  }

  // Hook WebAudio AudioContext.decodeAudioData (where Google AI Studio decodes the raw TTS audio for playback)
  const AudioContextClass = window.AudioContext || window.webkitAudioContext;
  if (AudioContextClass && AudioContextClass.prototype) {
    const origDecodeAudioData = AudioContextClass.prototype.decodeAudioData;
    AudioContextClass.prototype.decodeAudioData = function (audioData) {
      if (audioData instanceof ArrayBuffer && audioData.byteLength >= 400) {
        sendAudioBuffer(audioData.slice(0), 'AudioContext.decodeAudioData');
      }
      return origDecodeAudioData.apply(this, arguments);
    };
  }

  // Hook URL.createObjectURL
  const origCreateObjectURL = URL.createObjectURL;
  URL.createObjectURL = function (obj) {
    const url = origCreateObjectURL.apply(this, arguments);
    try {
      if (obj instanceof Blob && (obj.type.includes('audio') || obj.type.includes('wav') || obj.size >= 400)) {
        const reader = new FileReader();
        reader.onload = function () {
          if (reader.result instanceof ArrayBuffer) {
            sendAudioBuffer(reader.result, 'URL.createObjectURL');
          }
        };
        reader.readAsArrayBuffer(obj);
      }
    } catch (e) {}
    return url;
  };

  // Hook HTMLAnchorElement.prototype.click
  const origAnchorClick = HTMLAnchorElement.prototype.click;
  HTMLAnchorElement.prototype.click = function () {
    try {
      if (this.href && !this.href.startsWith('blob:null') && (this.href.startsWith('blob:') || this.href.includes('.wav') || this.download)) {
        fetch(this.href)
          .then((r) => r.arrayBuffer())
          .then((buf) => {
            if (buf.byteLength >= 400) {
              sendAudioBuffer(buf, 'HTMLAnchorElement.click');
            }
          })
          .catch(() => {});
      }
    } catch (e) {}
    return origAnchorClick.apply(this, arguments);
  };
})();
